45	  id                      UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
46	  studio_id               UUID        NOT NULL REFERENCES public.studios(id) ON DELETE CASCADE,
47	  -- nullable: studios can list placeholder artists before they sign up
